package android.util;
public class DisplayMetrics {public int widthPixels,heightPixels,densityDpi=160;public float density=1,scaledDensity=1,xdpi=160,ydpi=160;public void setTo(DisplayMetrics m){widthPixels=m.widthPixels;heightPixels=m.heightPixels;densityDpi=m.densityDpi;density=m.density;scaledDensity=m.scaledDensity;xdpi=m.xdpi;ydpi=m.ydpi;}}
